/* ===== 39_update.js ===== */
const MJ_BUILTIN_UPDATE_URL = 'https://raw.githubusercontent.com/zzhengpei-sys/Beyond-The-Mist/main/mujian-update.json';
const MJ_UPDATE_NOTICE_INTERVAL = 15 * 60 * 1000;
const MJ_PENDING_RELEASE_KEY = Symbol.for('mujian.pending-release');
let MJ_UPDATE_RUNNING = false;
let MJ_AVAILABLE_UPDATE = '';
let MJ_UPDATE_MANIFEST_REQUEST = null;
let MJ_UPDATE_NOTICE_TIMER = null;
let MJ_LAST_UPDATE_NOTICE_CHECK = null;
const MJ_NOTIFIED_VERSIONS = new Set();

function mjUpdateUrl(address, base) {
  const url = new URL(address, base);
  if (url.protocol !== 'https:' || url.username || url.password)
    throw new Error('更新地址必须是无登录信息的 HTTPS 链接');
  return url;
}

function mjCompareRelease(a, b) {
  const parse = version => {
    if (!/^\d{1,6}\.\d{1,6}\.\d{1,6}$/.test(version)) throw new Error('更新清单的版本号无效');
    return version.split('.').map(Number);
  };
  const x = parse(a);
  const y = parse(b);
  return x[0] - y[0] || x[1] - y[1] || x[2] - y[2];
}

async function mjDownloadReleaseFile(url, limit) {
  const response = await fetch(url.href, {
    cache: 'no-store', credentials: 'omit', referrerPolicy: 'no-referrer',
    redirect: 'error', signal: AbortSignal.timeout(20000),
  });
  if (!response.ok) throw new Error(`下载失败（HTTP ${response.status}）`);
  if (Number(response.headers.get('content-length')) > limit) throw new Error('更新文件过大');
  const bytes = await response.arrayBuffer();
  if (bytes.byteLength > limit) throw new Error('更新文件过大');
  return bytes;
}

function mjUpdateButtonLabel() {
  return MJ_AVAILABLE_UPDATE ? `有新版本 v${MJ_AVAILABLE_UPDATE}` : '检查更新';
}

function mjReadUpdateManifest() {
  if (!MJ_UPDATE_MANIFEST_REQUEST) {
    MJ_UPDATE_MANIFEST_REQUEST = (async () => {
      const url = mjUpdateUrl(MJ_BUILTIN_UPDATE_URL);
      const bytes = await mjDownloadReleaseFile(url, 32 * 1024);
      const manifest = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes));
      if (manifest?.project !== 'mujian' || typeof manifest.version !== 'string' ||
          typeof manifest.script !== 'string' || !manifest.script || !/^[a-f0-9]{64}$/.test(manifest.sha256))
        throw new Error('更新清单格式有误');
      const comparison = mjCompareRelease(manifest.version, MJ_VERSION);
      const scriptUrl = mjUpdateUrl(manifest.script, url);
      if (scriptUrl.origin !== url.origin) throw new Error('脚本与更新清单必须来自同一个发布站点');
      MJ_AVAILABLE_UPDATE = comparison > 0 ? manifest.version : '';
      const button = MJ_PANEL?.querySelector('[data-act="check-plugin-update"]');
      if (button) {
        button.textContent = mjUpdateButtonLabel();
        button.classList.toggle('has-update', !!MJ_AVAILABLE_UPDATE);
      }
      return { manifest, comparison, scriptUrl };
    })().finally(() => { MJ_UPDATE_MANIFEST_REQUEST = null; });
  }
  return MJ_UPDATE_MANIFEST_REQUEST;
}

function mjShowUpdateNotice() {
  const version = MJ_AVAILABLE_UPDATE;
  if (!version || MJ_UPDATE_RUNNING || mjDoc().visibilityState === 'hidden' || MJ_NOTIFIED_VERSIONS.has(version)) return;
  MJ_NOTIFIED_VERSIONS.add(version);
  mjToast(`迷雾之外有新版本 v${version}，请打开插件，点击左上角更新。`, 'info', 8000);
}

async function mjCheckUpdateNotice() {
  if (mjDoc().visibilityState === 'hidden' || MJ_UPDATE_RUNNING) return;
  const now = Date.now();
  if (MJ_LAST_UPDATE_NOTICE_CHECK !== null && now - MJ_LAST_UPDATE_NOTICE_CHECK < MJ_UPDATE_NOTICE_INTERVAL) {
    mjShowUpdateNotice();
    return;
  }
  MJ_LAST_UPDATE_NOTICE_CHECK = now;
  try {
    await mjReadUpdateManifest();
    mjShowUpdateNotice();
  } catch {
    // 自动检查失败时交给下一轮或用户手动检查。
  }
}

function mjStartUpdateNotices() {
  if (MJ_UPDATE_NOTICE_TIMER !== null) return;
  mjDoc().addEventListener('visibilitychange', mjCheckUpdateNotice);
  MJ_UPDATE_NOTICE_TIMER = setInterval(mjCheckUpdateNotice, 60 * 1000);
  void mjCheckUpdateNotice();
}

function mjReplaceRunningScript(trees, id, code) {
  let matches = 0;
  const replace = script => {
    if (script.type !== 'script' || script.id !== id) return script;
    matches++;
    if (script.content.match(/const MJ_VERSION = '([\d.]+)';/)?.[1] !== MJ_VERSION)
      throw new Error('当前脚本已变更，请重新打开插件再试');
    return { ...script, content: code };
  };
  const updated = trees.map(node => node.type === 'folder' ? { ...node, scripts: node.scripts.map(replace) } : replace(node));
  if (matches !== 1) throw new Error('无法唯一定位当前脚本，请确认迷雾之外安装在全局脚本库');
  return updated;
}

async function mjWaitForSavedRelease(host, headers, id, code, stillCurrent = () => true) {
  // 酒馆助手先改内存，随后由酒馆防抖保存。
  for (const delay of [1200, 1000, 2000, 3000, 4000]) {
    await new Promise(resolve => host.setTimeout(resolve, delay));
    if (!stillCurrent()) return false;
    try {
      const response = await host.fetch('/api/settings/get', {
        method: 'POST', headers, body: '{}', cache: 'no-store', signal: AbortSignal.timeout(3500),
      });
      if (!response.ok) continue;
      const { settings } = await response.json();
      const saved = (typeof settings === 'string' ? JSON.parse(settings) : settings)?.extension_settings;
      const trees = saved?.tavern_helper?.script?.scripts ?? saved?.TavernHelper?.script?.scripts;
      if (!Array.isArray(trees)) continue;
      const match = script => script?.type === 'script' && script.id === id && script.content === code;
      if (trees.some(node => node?.type === 'folder' ? node.scripts?.some(match) : match(node))) return stillCurrent();
    } catch {
      // 此时保留页面，给酒馆继续保存或恢复连接的机会。
    }
  }
  throw new Error('酒馆尚未确认保存新版脚本，页面已保留。请在酒馆助手确认脚本已保存后再刷新');
}

async function mjFinishPendingRelease(host, pending) {
  if (host[MJ_PENDING_RELEASE_KEY] !== pending || pending.owner === MJ_VERSION) return;
  // 新版启动时接管。旧版即使恢复执行，也不能抢回确认流程或重复刷新。
  if (pending.owner && MJ_VERSION !== pending.version) return;
  pending.owner = MJ_VERSION;
  const stillCurrent = () => host[MJ_PENDING_RELEASE_KEY] === pending && pending.owner === MJ_VERSION;
  try {
    if (!await mjWaitForSavedRelease(host, pending.headers, pending.id, pending.code, stillCurrent) || !stillCurrent()) return;
    delete host[MJ_PENDING_RELEASE_KEY];
    try {
      host.location.reload();
    } catch {
      mjToast(`已安装 v${pending.version}，酒馆未能自动刷新，请手动刷新页面。`, 'ok', 6000);
    }
  } catch (error) {
    if (!stillCurrent()) return;
    delete host[MJ_PENDING_RELEASE_KEY];
    mjToast(error.message || String(error), 'warn', 7000);
  }
}

function mjResumePendingRelease() {
  const host = mjWin();
  const pending = host[MJ_PENDING_RELEASE_KEY];
  const id = typeof getScriptId === 'function' ? getScriptId() : '';
  if (!id || pending?.id !== id || pending.version !== MJ_VERSION) return;
  void mjFinishPendingRelease(host, pending);
}

async function mjCheckForUpdate(button) {
  if (MJ_UPDATE_RUNNING) return;
  MJ_UPDATE_RUNNING = button.disabled = true;
  try {
    const { manifest, comparison, scriptUrl } = await mjReadUpdateManifest();
    if (comparison === 0) return mjToast(`当前 v${MJ_VERSION} 已是最新版本`);
    if (comparison < 0) return mjToast(`当前 v${MJ_VERSION} 已高于发布版本 v${manifest.version}`);
    MJ_NOTIFIED_VERSIONS.add(manifest.version);
    const id = typeof getScriptId === 'function' ? getScriptId() : '';
    const updateTrees = typeof TavernHelper !== 'undefined' && TavernHelper.updateScriptTreesWith;
    if (!id || typeof updateTrees !== 'function') throw new Error('请升级酒馆助手，并从全局脚本库运行迷雾之外');
    if (!globalThis.crypto?.subtle) throw new Error('当前页面无法校验更新，请通过本机地址或 HTTPS 打开酒馆');
    const bytes = await mjDownloadReleaseFile(scriptUrl, 8 * 1024 * 1024);
    const digest = new Uint8Array(await globalThis.crypto.subtle.digest('SHA-256', bytes));
    if (Array.from(digest, b => b.toString(16).padStart(2, '0')).join('') !== manifest.sha256)
      throw new Error('更新文件校验失败，请稍后再试');
    const code = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
    if (!code.startsWith('/*!') || !code.includes(`const MJ_VERSION = '${manifest.version}';`))
      throw new Error('脚本版本与更新清单不一致');
    if (!await mjConfirm(`更新迷雾之外到 v${manifest.version}？`, `来源 ${scriptUrl.origin}。安装完成后会自动刷新酒馆页面，保留本插件的设置和数据。请先保存页面中的其他编辑。`)) return;
    if (MJ_RUNNING || MJ_PLOT_RUNNING || MJ_DIY_JOB) throw new Error('请等当前演化、规划或 DIY 任务结束后再更新');
    const host = mjWin();
    if (host[MJ_PENDING_RELEASE_KEY]) return mjToast('正在确认酒馆已保存更新，请稍候。');
    const ctx = host.SillyTavern?.getContext?.();
    if (typeof ctx?.getRequestHeaders !== 'function' || typeof host.fetch !== 'function')
      throw new Error('当前酒馆无法确认脚本已保存，请通过酒馆助手手动更新');
    const headers = ctx.getRequestHeaders();
    if (MJ_DIRTY.settings) mjSaveSettings();
    // 原位替换可能立即卸载当前 iframe。先把交接信息留在酒馆页面，供新版启动时接手。
    const pending = { id, version: manifest.version, code, headers, owner: '' };
    host[MJ_PENDING_RELEASE_KEY] = pending;
    try {
      await updateTrees(trees => mjReplaceRunningScript(trees, id, code), { type: 'global' });
    } catch (error) {
      if (host[MJ_PENDING_RELEASE_KEY] !== pending || pending.owner === pending.version) return;
      delete host[MJ_PENDING_RELEASE_KEY];
      throw error;
    }
    if (host[MJ_PENDING_RELEASE_KEY] !== pending || pending.owner === pending.version) return;
    await mjFinishPendingRelease(host, pending);
  } catch (error) {
    mjToast(`更新失败：${error.message || error}`, 'warn', 6000);
  } finally {
    MJ_UPDATE_RUNNING = button.disabled = false;
    const current = MJ_PANEL?.querySelector('[data-act="check-plugin-update"]');
    if (current) current.disabled = false;
  }
}


