function mjTheme() {
  const t = String(MJ_SETTINGS?.界面?.主题 || 'tea');
  const alias = { night: 'tea', dark: 'tea', day: 'warm', light: 'warm', eye: 'sage' };
  const v = alias[t] || t;
  return MJ_THEMES[v] ? v : 'tea';
}

